import { Link } from "react-router-dom";
import Teachersidebar from "./Teachersidebar";
import {Routes as Switch, Route} from 'react-router-dom';
import { useState,useEffect } from "react";
import axios from "axios";
import { useParams } from "react-router-dom";
const baseUrl="http://127.0.0.1:8000/api";
function AddChapter(){
    const[chapterData,setChapterData]=useState({
        "title":'',
        "description":'',
        "video":"",
        "remarks":''
    });
const handleChange=(event)=>{
    setChapterData({
        ...chapterData,
        [event.target.name]:event.target.value
    });
}
const handleFileChange=(event)=>{
    setChapterData({
        ...chapterData, 
        [event.target.name]:event.target.files[0]
    });
}
 const {course_id}=useParams();
const submitForm=(event)=>{
    event.preventDefault();
    const chapterFormData=new FormData();  
   
    formData.append("course",course_id); 
    formData.append("title",chapterData.title);
    formData.append("description",chapterData.description);  
    formData.append("video",chapterData.video,chapterData.video.name);      
    formData.append("remarks",chapterData.remarks);
    try{
        axios.post(baseUrl+"/chapter/",chapterFormData,{
            headers:{
                'content-type':'multipart/form-data'
            } 
        }).then((response)=>{
            //console.log(response.data);
            window.location.href="/teacher-mycourses"
        });}
        catch(error){
            console.log(error);
        }   
}

 return (
    <div className="container mt-4">
        <div className="row">
            <aside className="col-md-3">
                <Teachersidebar></Teachersidebar>
            </aside>
            <section className="col-md-9">
                <div className="card">
                        <h5 className="card-header">Add Chapter</h5>
                        <div className="card-body">
                            <form>
                                <div className="mb-3">
                                    <label htmlFor="name" className="form-label">Title</label>
                                    <input type="text" onChange={handleChange} name="title" className="form-control" id="name"/>
                                </div>
                                <div className="mb-3">
                                    <label htmlFor="description" className="form-label">Description</label>
                                    <textarea className="form-control" onChange={handleChange} name="description"></textarea>
                                </div>
                                <div className="mb-3">
                                    <label for="video" className="form-label">video</label>
                                    <input type="file" onChange={handleFileChange} name="video" id="vid" className="form-control"/>
                                </div>

                                <div className="mb-3">
                                    <label htmlFor="Technology" className="form-label">Remarks</label>
                                    <textarea className="form-control" onChange={handleChange} name="remarks"></textarea>
    
                                </div>
                                <button type="submit" onSubmit={submitForm} className="btn btn-primary">submit</button>
                            </form>
                        </div>
                    </div>
            </section>
        </div>
      </div>
 );
}
export default AddChapter
